import { ScrollView, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { HeaderBar, SettingsItem } from '@/components'
import { router, useLocalSearchParams } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

export const ProjectSettingsScreen = () => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()

	const { projectGroupId, projectId } = useLocalSearchParams<{
		projectGroupId?: string
		projectId?: string
	}>()

	const onClose = () => {
		router.back()
	}

	const handleAssets = () => {
		router.push({
			pathname: '/project/project-assets',
			params: { projectGroupId, projectId }
		})
	}

	const handleBrandingIcons = () => {}

	const handleSavedSecrets = () => {
		router.push({
			pathname: '/project/project-secrets',
			params: {
				projectGroupId
			}
		})
	}

	return (
		<ScrollView
			style={styles.scrollView(theme)}
			showsVerticalScrollIndicator={false}
			contentContainerStyle={{
				paddingTop: insets.top,
				paddingBottom: insets.bottom + 16,
				gap: 32
			}}
		>
			<HeaderBar title="Settings" onClose={onClose} showBackButton />

			<View style={styles.section}>
				<SettingsItem
					title="Assets"
					subtitle="Upload images, videos, and other files to your project."
					onPress={handleAssets}
					type="button"
					appearance="primary"
				/>

				<SettingsItem
					title="Branding & icons"
					subtitle="Set the icons that represent your app."
					onPress={handleBrandingIcons}
					type="button"
					appearance="primary"
				/>

				<SettingsItem
					title="Saved secrets"
					subtitle="Store API keys, passwords, and other sensitive data."
					onPress={handleSavedSecrets}
					type="button"
					appearance="primary"
				/>
			</View>
		</ScrollView>
	)
}

const styles = defineStyles({
	scrollView: (theme: Theme) => ({
		backgroundColor: colors[theme].background,
		paddingHorizontal: 24
	}),
	section: {
		gap: 28
	}
})
